//! Dragon Ball Z: Budokai Tenkaichi 3, translated from the decompilation's C into Rust.
//!
//! `tu/` holds one module per C source, generated by tools/translate from the same preprocessed sources the PC
//! port compiles; `gen/` the generated memory layout and glue; `rt/` the machine model (PS2 memory and float
//! arithmetic) and `host/` the platform services the game asks the PS2 system software for.
#![allow(clippy::all)]
pub mod rt;
pub mod host;
pub mod gen {
    pub mod sym;
    pub mod fid;
    pub mod funcs;
    pub mod dispatch;
    pub mod data;
}
pub mod tu;
